    close.style.cssText =
      'margin-top:10px;padding:6px 28px;border:none;border-radius:6px;' +
      'background:#9e9e9e;color:#fff;cursor:pointer;font-size:12px;';
    close.addEventListener('click', () => (mask.style.display = 'none'));
    card.appendChild(title);
